from typing import Annotated
from pydantic import Field
from agent_framework import tool

@tool(name='weather_tool', description='Retrieves weather for any location')
def get_weather(
    location: Annotated[str, Field(description='The location.')],
) -> str:
    return f'The weather in {location} is cloudy, 15C.'

agent = client.as_agent(instructions='You are helpful.', tools=[get_weather])

client.function_invocation_configuration.update({
    'max_iterations': 5,
    'max_function_calls': 20,
    'max_duration_seconds': 30.0,
})
client.function_invocation_configuration['allow_concurrent_invocation'] = False
